      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  }).value;
  // Line 1: 10 * 8500 = 85000, discount 10% = 8500, after discount = 76500
  // Line 2: 10 * 9500 = 95000, discount 20% = 19000, after discount = 76000
  // Total discount: 27500
  // Subtotal: 180000
  // VAT: 76500 * 21% + 76000 * 21% = 16065 + 15960 = 32025
  // Total: 180000 - 27500 + 32025 = 184525

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 180000);
  assert.equal(totals.discount, 27500);
  assert.equal(totals.vat, 32025);
  assert.equal(totals.total, 184525);
});

test('invoiceTotals handles decimal discounts with rounding', () => {
